    /**
     * @method
     * @name coinex#fetchCurrencies
     * @description fetches all available currencies on an exchange
     * @see https://docs.coinex.com/api/v2/assets/deposit-withdrawal/http/list-all-deposit-withdrawal-config
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} an associative dictionary of currencies
     */
    public async override Task<IDictionary<string, object>> fetchCurrencies(object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        Dictionary<string, object> response = await this.v2PublicGetAssetsAllDepositWithdrawConfig(parameters);
        //
        //     {
        //         "code": 0,
        //         "data": [
        //             {
        //                 "asset": {
        //                     "ccy": "CET",
        //                     "deposit_enabled": true,
        //                     "withdraw_enabled": true,
        //                     "inter_transfer_enabled": true,
        //                     "is_st": false
        //                 },
        //                 "chains": [
        //                     {
        //                         "chain": "CSC",
        //                         "min_deposit_amount": "0.8",
        //                         "min_withdraw_amount": "8",
        //                         "deposit_enabled": true,
        //                         "withdraw_enabled": true,
        //                         "deposit_delay_minutes": 0,
        //                         "safe_confirmations": 10,
        //                         "irreversible_confirmations": 20,
        //                         "deflation_rate": "0",
        //                         "withdrawal_fee": "0.026",
        //                         "withdrawal_precision": 8,
        //                         "memo": "",
        //                         "is_memo_required_for_deposit": false,
        //                         "explorer_asset_url": ""
        //                     },
        //                 ]
        //             }
        //         ],
        //         "message": "OK"
        //     }
        //
        List<object> data = this.safeList(response, "data", new List<object>() {});
        return this.parseCurrencies(data);
    }

    public override Dictionary<string, object> parseCurrency(object coin)
    {
        IDictionary<string, object> asset = this.safeDict(coin, "asset", new Dictionary<string, object>() {});
        string? currencyId = this.safeString(asset, "ccy");
        List<object> chains = this.safeList(coin, "chains", new List<object>() {});
        string? code = this.safeCurrencyCode(currencyId);
        Dictionary<string, object> networks = new Dictionary<string, object>() {};
        for (int j = 0; j < chains.Count; j++)
        {
            IDictionary<string, object> chain = ((IDictionary<string, object>)chains[j]);
            string? networkId = this.safeString(chain, "chain");
            string? networkCode = this.networkIdToCode(networkId, code);
            if ((networkId == null))
            {
                continue;
            }
            Dictionary<string, object> network = new Dictionary<string, object>() {
                { "id", networkId },
                { "network", networkCode },
                { "name", null },
                { "active", null },
                { "deposit", this.safeBool(chain, "deposit_enabled") },
                { "withdraw", this.safeBool(chain, "withdraw_enabled") },
                { "fee", this.safeNumber(chain, "withdrawal_fee") },
                { "precision", this.parseNumber(this.parsePrecision(this.safeString(chain, "withdrawal_precision"))) },
                { "limits", new Dictionary<string, object>() {
                    { "amount", new Dictionary<string, object>() {
                        { "min", null },
                        { "max", null },
                    } },
                    { "deposit", new Dictionary<string, object>() {
                        { "min", this.safeNumber(chain, "min_deposit_amount") },
                        { "max", null },
                    } },
                    { "withdraw", new Dictionary<string, object>() {
                        { "min", this.safeNumber(chain, "min_withdraw_amount") },
                        { "max", null },
                    } },
                } },
                { "info", chain },
            };
            if ((networkCode != null))
            {
                networks[(string)networkCode] = network;
            }
        }
        return this.safeCurrencyStructure(new Dictionary<string, object>() {
            { "id", currencyId },
            { "code", code },
            { "name", null },
            { "active", null },
            { "deposit", this.safeBool(asset, "deposit_enabled") },
            { "withdraw", this.safeBool(asset, "withdraw_enabled") },
            { "fee", null },
            { "precision", null },
            { "limits", new Dictionary<string, object>() {
                { "amount", new Dictionary<string, object>() {
                    { "min", null },
                    { "max", null },
                } },
                { "deposit", new Dictionary<string, object>() {
                    { "min", null },
                    { "max", null },
                } },
                { "withdraw", new Dictionary<string, object>() {
                    { "min", null },
                    { "max", null },
                } },
            } },
            { "networks", networks },
            { "type", "crypto" },
            { "info", coin },
        });
    }

    /**
     * @method
     * @name coinex#fetchMarkets
     * @description retrieves data on all markets for coinex
     * @see https://docs.coinex.com/api/v2/spot/market/http/list-market
     * @see https://docs.coinex.com/api/v2/futures/market/http/list-market
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object[]} an array of objects representing market data
     */
    public async override Task<List<ccxt.MarketInterface>> FetchMarkets(object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        List<object> promisesUnresolved = new List<object> {this.FetchSpotMarkets(parameters), this.FetchContractMarkets(parameters)};
        List<object> promises = await promiseAll(promisesUnresolved);
        object spotMarkets = (promises != null && 0 < promises.Count ? promises[0] : null);
        object swapMarkets = (promises != null && 1 < promises.Count ? promises[1] : null);
        return ccxt.BaseExchange.ToMarketInterfaceList(this.arrayConcat(spotMarkets, swapMarkets));
    }

    public async virtual Task<List<ccxt.MarketInterface>> FetchSpotMarkets(object parameters)
    {
        Dictionary<string, object> response = await this.v2PublicGetSpotMarket(parameters);
        //
        //     {
        //         "code": 0,
        //         "data": [
        //             {
        //                 "market": "BTCUSDT",
        //                 "taker_fee_rate": "0.002",
        //                 "maker_fee_rate": "0.002",
        //                 "min_amount": "0.0005",
