    /**
     * @method
     * @name coinex#fetchOrderBook
     * @description fetches information on open orders with bid (buy) and ask (sell) prices, volumes and other data
     * @see https://docs.coinex.com/api/v2/spot/market/http/list-market-depth
     * @see https://docs.coinex.com/api/v2/futures/market/http/list-market-depth
     * @param {string} symbol unified symbol of the market to fetch the order book for
     * @param {int} [limit] the maximum amount of order book entries to return
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} an [order book structure]{@link https://docs.ccxt.com/?id=order-book-structure}
     */
    public async override Task<ccxt.OrderBook> FetchOrderBook(string symbol, Int64? limit = null, object parameters = null)
    {
        Int64? limitVar = limit;
        limitVar ??= ((Int64?)20);
        parameters ??= new Dictionary<string, object>();
        if ((this.markets == null))
        {
            await this.loadMarkets();
        }
        Dictionary<string, object> market = this.market(symbol);
        object limitValue = limitVar;
        if ((limitValue == null))
        {
            limitValue = 20;
        }
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "market", (market.ContainsKey("id") ? market["id"] : null) },
            { "limit", limitValue },
            { "interval", "0" },
        };
        Dictionary<string, object> response = null;
        if ((((market.ContainsKey("swap") ? market["swap"] : null) as bool?) == true))
        {
            response = await this.v2PublicGetFuturesDepth(this.extend(request, parameters));
        } else
        {
            response = await this.v2PublicGetSpotDepth(this.extend(request, parameters));
        }
        IDictionary<string, object> data = this.safeDict(response, "data", new Dictionary<string, object>() {});
        IDictionary<string, object> depth = this.safeDict(data, "depth", new Dictionary<string, object>() {});
        Int64? timestamp = this.safeInteger(depth, "updated_at");
        return ccxt.BaseExchange.ToOrderBook(this.parseOrderBook(depth, symbol, timestamp));
    }

    public override Dictionary<string, object> parseTrade(object trade, object market = null)
    {
        //
        // Spot and Swap fetchTrades (public)
        //
        //     {
        //         "amount": "0.00049432",
        //         "created_at": 1713849825667,
        //         "deal_id": 4137517302,
        //         "price": "66251",
        //         "side": "buy"
        //     }
        //
        // Spot and Margin fetchMyTrades (private)
        //
        //     {
        //         "amount": "0.00010087",
        //         "created_at": 1714618087585,
        //         "deal_id": 4161200602,
        //         "margin_market": "",
        //         "market": "BTCUSDT",
        //         "order_id": 117654919342,
        //         "price": "57464.04",
        //         "side": "sell"
        //     }
        //
        // Swap fetchMyTrades (private)
        //
        //     {
        //         "deal_id": 1180222387,
        //         "created_at": 1714119054558,
        //         "market": "BTCUSDT",
        //         "side": "buy",
        //         "order_id": 136915589622,
        //         "price": "64376",
        //         "amount": "0.0001",
        //         "role": "taker",
        //         "fee": "0.0299",
        //         "fee_ccy": "USDT"
        //     }
        //
        Int64? timestamp = this.safeInteger(trade, "created_at");
        string? defaultType = this.safeString(this.options, "defaultType");
        if ((market != null))
        {
            defaultType = this.safeString(market, "type");
        }
        string? marketId = this.safeString(trade, "market");
        Dictionary<string, object> marketResolved = this.safeMarket(marketId, market, null, defaultType);
        string? feeCostString = this.safeString(trade, "fee");
        Dictionary<string, object> fee = null;
        if ((feeCostString != null))
        {
            string? feeCurrencyId = this.safeString(trade, "fee_ccy");
            string? feeCurrencyCode = this.safeCurrencyCode(feeCurrencyId);
            fee = new Dictionary<string, object>() {
                { "cost", feeCostString },
                { "currency", feeCurrencyCode },
            };
        }
        return this.safeTrade(new Dictionary<string, object>() {
            { "info", trade },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "symbol", (marketResolved != null && ((IDictionary<string, object>)marketResolved).ContainsKey("symbol") ? ((IDictionary<string, object>)marketResolved)["symbol"] : null) },
            { "id", this.safeString(trade, "deal_id") },
            { "order", this.safeString(trade, "order_id") },
            { "type", null },
            { "side", this.safeString(trade, "side") },
            { "takerOrMaker", this.safeString(trade, "role") },
            { "price", this.safeString(trade, "price") },
            { "amount", this.safeString(trade, "amount") },
            { "cost", this.safeString(trade, "deal_money") },
            { "fee", fee },
        }, marketResolved);
    }

    /**
     * @method
     * @name coinex#fetchTrades
     * @description get the list of the most recent trades for a particular symbol
     * @see https://docs.coinex.com/api/v2/spot/market/http/list-market-deals
     * @see https://docs.coinex.com/api/v2/futures/market/http/list-market-deals
     * @param {string} symbol unified symbol of the market to fetch trades for
     * @param {int} [since] timestamp in ms of the earliest trade to fetch
     * @param {int} [limit] the maximum amount of trades to fetch
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {Trade[]} a list of [trade structures]{@link https://docs.ccxt.com/?id=public-trades}
     */
    public async override Task<List<ccxt.Trade>> FetchTrades(string symbol, Int64? since = null, Int64? limit = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        if ((this.markets == null))
        {
            await this.loadMarkets();
        }
        Dictionary<string, object> market = this.market(symbol);
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "market", (market.ContainsKey("id") ? market["id"] : null) },
        };
        if ((limit != null))
        {
            request["limit"] = Math.Min(limit.Value, 1000);
        }
        Dictionary<string, object> response = null;
        if ((((market.ContainsKey("swap") ? market["swap"] : null) as bool?) == true))
        {
            response = await this.v2PublicGetFuturesDeals(this.extend(request, parameters));
        } else
        {
            response = await this.v2PublicGetSpotDeals(this.extend(request, parameters));
        }
        //
        // Spot and Swap
        //
        //     {
        //         "code": 0,
        //         "data": [
        //             {
        //                 "amount": "0.00049432",
        //                 "created_at": 1713849825667,
        //                 "deal_id": 4137517302,
        //                 "price": "66251",
        //                 "side": "buy"
        //             },
        //         ],
        //         "message": "OK"
        //     }
        //
        return ccxt.BaseExchange.ToTradeList(this.parseTrades(GetValue(response, "data"), market, since, limit));
    }

