        //         "client_id": "x-167673045-a7d7714c6478acf6",
        //         "created_at": 1714187923820,
        //         "market": "BTCUSDT",
        //         "market_type": "FUTURES",
        //         "price": "61000",
        //         "side": "buy",
        //         "stop_id": 136984426097,
        //         "trigger_direction": "higher",
        //         "trigger_price": "62000",
        //         "trigger_price_type": "latest_price",
        //         "type": "limit",
        //         "updated_at": 1714187974363
        //     }
        //
        // Spot and Margin trigger fetchOpenOrders, fetchClosedOrders
        //
        //     {
        //         "stop_id": 117586439530,
        //         "market": "BTCUSDT",
        //         "market_type": "SPOT",
        //         "ccy": "BTC",
        //         "side": "buy",
        //         "type": "limit",
        //         "amount": "0.0001",
        //         "price": "51000",
        //         "trigger_price": "52000",
        //         "trigger_direction": "higher",
        //         "trigger_price_type": "mark_price",
        //         "client_id": "x-167673045-df61777094c69312",
        //         "created_at": 1714551237335,
        //         "updated_at": 1714551237335
        //     }
        //
        string? rawStatus = this.safeString(order, "status");
        Int64? timestamp = this.safeInteger(order, "created_at");
        Int64? updatedTimestamp = this.safeInteger(order, "updated_at");
        if ((updatedTimestamp == 0))
        {
            updatedTimestamp = timestamp;
        }
        string? marketId = this.safeString(order, "market");
        string? defaultType = this.safeString(this.options, "defaultType");
        string? orderType = this.safeStringLower(order, "market_type", defaultType);
        if (orderType == "futures")
        {
            orderType = "swap";
        }
        string marketType = "spot";
        if (orderType == "swap")
        {
            marketType = "swap";
        }
        Dictionary<string, object> marketResolved = this.safeMarket(marketId, market, null, marketType);
        string? feeCurrencyId = this.safeString(order, "fee_ccy");
        string? feeCurrency = this.safeCurrencyCode(feeCurrencyId);
        if ((feeCurrency == null))
        {
            feeCurrency = this.safeString(marketResolved, "quote");
        }
        string? side = this.safeString(order, "side");
        if (side == "long")
        {
            side = "buy";
        } else if (side == "short")
        {
            side = "sell";
        }
        string? clientOrderId = this.safeString(order, "client_id");
        if (clientOrderId == "")
        {
            clientOrderId = null;
        }
        return this.safeOrder(new Dictionary<string, object>() {
            { "id", this.safeStringN(order, new List<object>() {"position_id", "order_id", "stop_id"}) },
            { "clientOrderId", clientOrderId },
            { "datetime", this.iso8601(timestamp) },
            { "timestamp", timestamp },
            { "lastTradeTimestamp", updatedTimestamp },
            { "status", this.parseOrderStatus(rawStatus) },
            { "symbol", (marketResolved != null && ((IDictionary<string, object>)marketResolved).ContainsKey("symbol") ? ((IDictionary<string, object>)marketResolved)["symbol"] : null) },
            { "type", this.safeString(order, "type") },
            { "timeInForce", null },
            { "postOnly", null },
            { "reduceOnly", null },
            { "side", side },
            { "price", this.safeString(order, "price") },
            { "triggerPrice", this.safeString(order, "trigger_price") },
            { "takeProfitPrice", this.safeNumber(order, "take_profit_price") },
            { "stopLossPrice", this.safeNumber(order, "stop_loss_price") },
            { "cost", this.safeString(order, "filled_value") },
            { "average", this.safeString(order, "avg_entry_price") },
            { "amount", this.safeString(order, "amount") },
            { "filled", this.safeString(order, "filled_amount") },
            { "remaining", this.safeString(order, "unfilled_amount") },
            { "trades", null },
            { "fee", new Dictionary<string, object>() {
                { "currency", feeCurrency },
                { "cost", this.safeString2(order, "quote_fee", "fee") },
            } },
            { "info", order },
        }, marketResolved);
    }

    /**
     * @method
     * @name coinex#createMarketBuyOrderWithCost
     * @description create a market buy order by providing the symbol and cost
     * @see https://viabtc.github.io/coinex_api_en_doc/spot/#docsspot003_trade003_market_order
     * @see https://docs.coinex.com/api/v2/spot/order/http/put-order
     * @param {string} symbol unified symbol of the market to create an order in
     * @param {float} cost how much you want to trade in units of the quote currency
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} an [order structure]{@link https://docs.ccxt.com/?id=order-structure}
     */
    public async override Task<ccxt.Order> CreateMarketBuyOrderWithCost(string symbol, double cost, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        if ((this.markets == null))
        {
            await this.loadMarkets();
        }
        Dictionary<string, object> market = this.market(symbol);
        if ((((market.ContainsKey("spot") ? market["spot"] : null) as bool?) != true))
        {
            throw new NotSupported ((this.id + " createMarketBuyOrderWithCost() supports spot orders only")) ;
        }
        ((IDictionary<string,object>)parameters)["createMarketBuyOrderRequiresPrice"] = false;
        return await this.CreateOrder(symbol, "market", "buy",ccxt.BaseExchange.ToDoubleArgRequired(cost),ccxt.BaseExchange.ToDoubleArg(null), parameters);
