    public override object parseMarketLeverageTiers(object info, IDictionary<string, object> market = null)
    {
        List<object> tiers = new List<object>() {};
        List<object> brackets = this.safeList(info, "level", new List<object>() {});
        object minNotional = 0;
        string? marketId = this.safeString(info, "market");
        Dictionary<string, object> marketResolved = this.safeMarket(marketId, market, null, "swap");
        for (int i = 0; i < brackets.Count; i++)
        {
            IDictionary<string, object> tier = ((IDictionary<string, object>)brackets[i]);
            double? maxNotional = this.safeNumber(tier, "amount");
            object curr = null;
            if ((((marketResolved != null && ((IDictionary<string, object>)marketResolved).ContainsKey("linear") ? ((IDictionary<string, object>)marketResolved)["linear"] : null) as bool?) == true))
            {
                curr = (marketResolved != null && ((IDictionary<string, object>)marketResolved).ContainsKey("base") ? ((IDictionary<string, object>)marketResolved)["base"] : null);
            } else
            {
                curr = (marketResolved != null && ((IDictionary<string, object>)marketResolved).ContainsKey("quote") ? ((IDictionary<string, object>)marketResolved)["quote"] : null);
            }
            object notional = minNotional;
            tiers.Add(new Dictionary<string, object>() {
                { "tier", this.sum(i, 1) },
                { "symbol", this.safeSymbol(marketId, marketResolved, null, "swap") },
                { "currency", curr },
                { "minNotional", notional },
                { "maxNotional", maxNotional },
                { "maintenanceMarginRate", this.safeNumber(tier, "maintenance_margin_rate") },
                { "maxLeverage", this.safeInteger(tier, "leverage") },
                { "info", tier },
            });
            minNotional = maxNotional;
        }
        return tiers;
    }

    public async virtual Task<Dictionary<string, object>> modifyMarginHelper(string? symbol, object amount, string? addOrReduce, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        if ((this.markets == null))
        {
            await this.loadMarkets();
        }
        Dictionary<string, object> market = this.market(symbol);
        string? rawAmount = this.amountToPrecision(symbol, amount);
        string? requestAmount = rawAmount;
        if ((addOrReduce == "reduce"))
        {
            requestAmount = Precise.stringNeg(rawAmount);
        }
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "market", (market.ContainsKey("id") ? market["id"] : null) },
            { "market_type", "FUTURES" },
            { "amount", requestAmount },
        };
        Dictionary<string, object> response = await this.v2PrivatePostFuturesAdjustPositionMargin(this.extend(request, parameters));
        //
        //     {
        //         "code": 0,
        //         "data": {
        //             "adl_level": 1,
        //             "ath_margin_size": "2.034928",
        //             "ath_position_amount": "0.0001",
        //             "avg_entry_price": "61047.84",
        //             "bkr_price": "30698.5600000000000004142",
        //             "close_avbl": "0.0001",
        //             "cml_position_value": "6.104784",
        //             "created_at": 1715488472908,
        //             "leverage": "3",
        //             "liq_price": "30852.82412060301507579316",
        //             "maintenance_margin_rate": "0.005",
        //             "maintenance_margin_value": "0.03051465",
        //             "margin_avbl": "3.034928",
        //             "margin_mode": "isolated",
        //             "market": "BTCUSDT",
        //             "market_type": "FUTURES",
        //             "max_position_value": "6.104784",
        //             "open_interest": "0.0001",
        //             "position_id": 306458800,
        //             "position_margin_rate": "0.49713929272518077625",
        //             "realized_pnl": "-0.003052392",
        //             "settle_price": "61047.84",
        //             "settle_value": "6.104784",
        //             "side": "long",
        //             "stop_loss_price": "0",
        //             "stop_loss_type": "",
        //             "take_profit_price": "0",
        //             "take_profit_type": "",
        //             "unrealized_pnl": "0",
        //             "updated_at": 1715488805563
        //         },
        //         "message": "OK"
        //     }
        //
        IDictionary<string, object> data = this.safeDict(response, "data", new Dictionary<string, object>() {});
        string? status = this.safeStringLower(response, "message");
        string type = "add";
        if ((addOrReduce == "reduce"))
        {
            type = "reduce";
        }
        return this.extend(this.parseMarginModification(data, market), new Dictionary<string, object>() {
            { "type", type },
            { "amount", this.parseNumber(amount) },
            { "status", status },
        });
    }

    public override Dictionary<string, object> parseMarginModification(object data, IDictionary<string, object> market = null)
    {
        //
        // addMargin/reduceMargin
        //
        //     {
        //         "adl_level": 1,
        //         "ath_margin_size": "2.034928",
        //         "ath_position_amount": "0.0001",
        //         "avg_entry_price": "61047.84",
        //         "bkr_price": "30698.5600000000000004142",
        //         "close_avbl": "0.0001",
        //         "cml_position_value": "6.104784",
        //         "created_at": 1715488472908,
        //         "leverage": "3",
        //         "liq_price": "30852.82412060301507579316",
        //         "maintenance_margin_rate": "0.005",
        //         "maintenance_margin_value": "0.03051465",
        //         "margin_avbl": "3.034928",
        //         "margin_mode": "isolated",
        //         "market": "BTCUSDT",
        //         "market_type": "FUTURES",
        //         "max_position_value": "6.104784",
        //         "open_interest": "0.0001",
        //         "position_id": 306458800,
        //         "position_margin_rate": "0.49713929272518077625",
        //         "realized_pnl": "-0.003052392",
        //         "settle_price": "61047.84",
        //         "settle_value": "6.104784",
        //         "side": "long",
        //         "stop_loss_price": "0",
        //         "stop_loss_type": "",
        //         "take_profit_price": "0",
        //         "take_profit_type": "",
        //         "unrealized_pnl": "0",
        //         "updated_at": 1715488805563
        //     }
        //
        // fetchMarginAdjustmentHistory
        //
        //     {
        //         "bkr_pirce": "24698.56000000000000005224",
        //         "created_at": 1715489978697,
        //         "leverage": "3",
        //         "liq_price": "24822.67336683417085432386",
        //         "margin_avbl": "3.634928",
        //         "margin_change": "-1.5",
        //         "margin_mode": "isolated",
        //         "market": "BTCUSDT",
        //         "market_type": "FUTURES",
        //         "open_interest": "0.0001",
        //         "position_id": 306458800,
        //         "settle_price": "61047.84"
        //     }
        //
        string? marketId = this.safeString(data, "market");
        Int64? timestamp = this.safeInteger2(data, "updated_at", "created_at");
        string? change = this.safeString(data, "margin_change");
        return new Dictionary<string, object>() {
            { "info", data },
            { "symbol", this.safeSymbol(marketId, market, null, "swap") },
            { "type", null },
            { "marginMode", "isolated" },
            { "amount", this.parseNumber(Precise.stringAbs(change)) },
            { "total", this.safeNumber(data, "margin_avbl") },
            { "code", this.safeString(market, "quote") },
            { "status", null },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
        };
    }

