    /**
     * @method
     * @name coinex#fetchFundingHistory
     * @description fetch the history of funding fee payments paid and received on this account
     * @see https://docs.coinex.com/api/v2/futures/position/http/list-position-funding-history
     * @param {string} symbol unified market symbol
     * @param {int} [since] the earliest time in ms to fetch funding history for
     * @param {int} [limit] the maximum number of funding history structures to retrieve
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a [funding history structure]{@link https://docs.ccxt.com/?id=funding-history-structure}
     */
    public async override Task<List<ccxt.FundingHistory>> FetchFundingHistory(string? symbol = null, Int64? since = null, Int64? limit = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        if ((symbol == null))
        {
            throw new ArgumentsRequired ((this.id + " fetchFundingHistory() requires a symbol argument")) ;
        }
        if ((this.markets == null))
        {
            await this.loadMarkets();
        }
        Dictionary<string, object> market = this.market(symbol);
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "market", (market.ContainsKey("id") ? market["id"] : null) },
            { "market_type", "FUTURES" },
        };
        IList<object> requestUntilparamsUntilVariable = (IList<object>)this.handleUntilOption("end_time", request, parameters);
        Dictionary<string, object> requestUntil = (Dictionary<string, object>)requestUntilparamsUntilVariable[0];
        IDictionary<string, object> paramsUntil = ((IDictionary<string, object>)requestUntilparamsUntilVariable[1]);
        if ((since != null))
        {
            ((IDictionary<string,object>)requestUntil)["start_time"] = since;
        }
        if ((limit != null))
        {
            ((IDictionary<string,object>)requestUntil)["limit"] = limit;
        }
        Dictionary<string, object> response = await this.v2PrivateGetFuturesPositionFundingHistory(this.extend(requestUntil, paramsUntil));
        //
        //     {
        //         "code": 0,
        //         "data": [
        //             {
        //                 "ccy": "USDT",
        //                 "created_at": 1715673620183,
        //                 "funding_rate": "0",
        //                 "funding_value": "0",
        //                 "market": "BTCUSDT",
        //                 "market_type": "FUTURES",
        //                 "position_id": 306458800,
        //                 "side": "long"
        //             },
        //         ],
        //         "message": "OK",
        //         "pagination": {
        //             "has_next": true
        //         }
        //     }
        //
        List<object> data = this.safeList(response, "data", new List<object>() {});
        List<object> result = new List<object>() {};
        for (int i = 0; i < data.Count; i++)
        {
            object entry = data[i];
            Int64? timestamp = this.safeInteger(entry, "created_at");
            string? currencyId = this.safeString(entry, "ccy");
            string? code = this.safeCurrencyCode(currencyId);
            result.Add(new Dictionary<string, object>() {
                { "info", entry },
                { "symbol", symbol },
                { "code", code },
                { "timestamp", timestamp },
                { "datetime", this.iso8601(timestamp) },
                { "id", this.safeNumber(entry, "position_id") },
                { "amount", this.safeNumber(entry, "funding_value") },
            });
        }
        return ccxt.BaseExchange.ToFundingHistoryList(result);
    }

