    public override Dictionary<string, object> parseFundingRate(object contract, IDictionary<string, object> market = null)
    {
        //
        // fetchFundingRate, fetchFundingRates, fetchFundingInterval
        //
        //     {
        //         "latest_funding_rate": "0",
        //         "latest_funding_time": 1715731200000,
        //         "mark_price": "61602.22",
        //         "market": "BTCUSDT",
        //         "max_funding_rate": "0.00375",
        //         "min_funding_rate": "-0.00375",
        //         "next_funding_rate": "0.00021074",
        //         "next_funding_time": 1715760000000
        //     }
        //
        Int64? currentFundingTimestamp = this.safeInteger(contract, "latest_funding_time");
        Int64? futureFundingTimestamp = this.safeInteger(contract, "next_funding_time");
        string? fundingTimeString = this.safeString(contract, "latest_funding_time");
        string? nextFundingTimeString = this.safeString(contract, "next_funding_time");
        string? millisecondsInterval = Precise.stringSub(nextFundingTimeString, fundingTimeString);
        string? marketId = this.safeString(contract, "market");
        return new Dictionary<string, object>() {
            { "info", contract },
            { "symbol", this.safeSymbol(marketId, market, null, "swap") },
            { "markPrice", this.safeNumber(contract, "mark_price") },
            { "indexPrice", null },
            { "interestRate", null },
            { "estimatedSettlePrice", null },
            { "timestamp", null },
            { "datetime", null },
            { "fundingRate", this.safeNumber(contract, "latest_funding_rate") },
            { "fundingTimestamp", currentFundingTimestamp },
            { "fundingDatetime", this.iso8601(currentFundingTimestamp) },
            { "nextFundingRate", this.safeNumber(contract, "next_funding_rate") },
            { "nextFundingTimestamp", futureFundingTimestamp },
            { "nextFundingDatetime", this.iso8601(futureFundingTimestamp) },
            { "previousFundingRate", null },
            { "previousFundingTimestamp", null },
            { "previousFundingDatetime", null },
            { "interval", this.parseFundingInterval(millisecondsInterval) },
        };
    }

    public virtual string? parseFundingInterval(object interval)
    {
        Dictionary<string, object> intervals = new Dictionary<string, object>() {
            { "3600000", "1h" },
            { "14400000", "4h" },
            { "28800000", "8h" },
            { "57600000", "16h" },
            { "86400000", "24h" },
        };
        return this.safeString(intervals, interval, interval);
    }

